<script setup lang="ts">import{computed,reactive,ref}from'vue';import{solveCircularPlate,type CircularPlateBoundary,type CircularPlateResult}from'../../../core/plate-shell';import{evaluateNumericExpression}from'../../../core/numeric';import{convertPresetValue,getPresetUnit,getUnitDefinition,normalizeToSI,type QuantityId,type UnitPresetId}from'../../../core/units';import CircularPlateDiagram from'./CircularPlateDiagram.vue';import CircularPlateResults from'./CircularPlateResults.vue';type F='radius'|'thickness'|'evaluation'|'e'|'nu'|'q';interface D extends Record<F,string>{boundary:CircularPlateBoundary|null};const DEF:D={boundary:null,radius:'1000',thickness:'20',evaluation:'0',e:'200000',nu:'.3',q:'0.01'};const d=reactive<D>({...DEF}),preset=ref<UnitPresetId>('engineering'),result=ref<CircularPlateResult|null>(null),errors=ref<string[]>([]);const fields:ReadonlyArray<readonly[F,QuantityId]>=[['radius','length'],['thickness','length'],['evaluation','length'],['e','elasticModulus'],['q','pressure']];const units=computed(()=>({l:sym('length'),e:sym('elasticModulus'),q:sym('pressure')}));function sym(q:QuantityId){const id=getPresetUnit(q,preset.value);return getUnitDefinition(q,id).symbol}function invalid(){result.value=null;errors.value=[]}function sw(n:UnitPresetId){if(n===preset.value)return;for(const[f,q]of fields)try{const v=evaluateNumericExpression(d[f]);const x=convertPresetValue(v,q,preset.value,n);if(x!==null)d[f]=String(Number(x.toPrecision(12)))}catch{}preset.value=n}function parse(f:F,l:string){try{return evaluateNumericExpression(d[f])}catch(e){throw new Error(`${l}：${e instanceof Error?e.message:'输入错误'}`)}}function si(f:F,l:string,q:QuantityId){return normalizeToSI(parse(f,l),q,getPresetUnit(q,preset.value))}function calc(){result.value=null;errors.value=[];try{if(!d.boundary)throw new Error('必须显式选择圆板周边条件');result.value=solveCircularPlate({calculatorId:'circular-plate',boundary:d.boundary,radiusM:si('radius','半径','length'),thicknessM:si('thickness','厚度','length'),evaluationRadiusM:si('evaluation','求值半径','length'),material:{elasticModulusPa:si('e','弹性模量','elasticModulus'),poissonRatio:parse('nu','泊松比')},pressurePa:si('q','均布载荷','pressure')})}catch(e){errors.value=[e instanceof Error?e.message:'计算失败']}}function reset(){Object.assign(d,DEF);preset.value='engineering';invalid()}</script>
<template><section class="calculator"><header><div><p>P3 · Gate P3-2</p><h2>实心圆板轴对称弯曲</h2><span>均布载荷；正面 z=+t/2；载荷与挠度 +z 为正。</span></div><div class="units" role="group" aria-label="圆板单位制"><button :aria-pressed="preset==='engineering'" :class="{active:preset==='engineering'}" @click="sw('engineering')">t–mm–s–N–MPa</button><button :aria-pressed="preset==='si'" :class="{active:preset==='si'}" @click="sw('si')">SI（kg–m–s–N–Pa）</button></div></header><div class="layout"><form class="form" @submit.prevent="calc"><fieldset><legend>1. 周边条件（必选）</legend><label><input v-model="d.boundary" type="radio" value="clamped" @change="invalid">周边固支</label><label><input v-model="d.boundary" type="radio" value="simply-supported" @change="invalid">周边简支</label></fieldset><h3>2. 几何</h3><label>半径 a<div><input v-model="d.radius" aria-label="圆板半径" @input="invalid"><b>{{units.l}}</b></div></label><label>厚度 t<div><input v-model="d.thickness" aria-label="圆板厚度" @input="invalid"><b>{{units.l}}</b></div></label><label>求值半径 r<div><input v-model="d.evaluation" aria-label="圆板求值半径" @input="invalid"><b>{{units.l}}</b></div></label><h3>3. 材料</h3><label>弹性模量 E<div><input v-model="d.e" aria-label="圆板弹性模量" @input="invalid"><b>{{units.e}}</b></div></label><label>泊松比 ν<div><input v-model="d.nu" aria-label="圆板泊松比" @input="invalid"><b>—</b></div></label><h3>4. 载荷</h3><label>均布压力 q（带符号）<div><input v-model="d.q" aria-label="圆板均布压力" @input="invalid"><b>{{units.q}}</b></div></label><section class="actions"><button>计算圆板</button><button type="button" @click="reset">重置</button></section></form><CircularPlateDiagram :boundary="d.boundary"/></div><div v-if="errors.length" class="error" role="alert">{{errors[0]}}</div><CircularPlateResults v-if="result" :result="result" :unit-preset="preset"/></section></template>
<style scoped>.calculator{display:grid;gap:18px}.calculator>header{display:flex;justify-content:space-between;gap:20px;padding:20px;border:1px solid var(--color-line);border-left:4px solid var(--color-brand);border-radius:12px;background:#f7faf9}header p{margin:0;color:var(--color-brand);font-size:10px;font-weight:800}h2{margin:4px 0}header span{color:var(--color-muted);font-size:11px}.units{display:flex;gap:5px}.units button,.actions button{border:1px solid var(--color-line);border-radius:8px;background:#fff}.units button{padding:8px}.units .active,.actions button:first-child{color:#fff;background:var(--color-brand)}.layout{display:grid;grid-template-columns:1.2fr .8fr;gap:18px;align-items:start}.form{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;padding:20px;border:1px solid var(--color-line);border-radius:var(--radius-large);background:#fff}.form fieldset,.form h3,.actions{grid-column:1/-1}.form fieldset{display:flex;gap:20px}.form label{display:grid;gap:5px;font-size:12px}.form label>div{display:grid;grid-template-columns:1fr auto;border:1px solid #cad5da;border-radius:8px;overflow:hidden}.form input{min-width:0;padding:11px;border:0}.form b{padding:11px;background:#f7f9fa;font-size:10px}.actions{display:flex;gap:8px}.actions button{padding:11px 15px}.error{padding:14px;color:#8f342d;background:#fff0ed}@media(max-width:900px){.calculator>header{flex-direction:column}.units{flex-direction:column}.layout{grid-template-columns:1fr}}@media(max-width:560px){.form{grid-template-columns:1fr}.form fieldset,.form h3,.actions{grid-column:auto}.form fieldset,.actions{flex-direction:column}}</style>
